            other => {
                if other.starts_with('-') {
                    eprintln!("error: Found argument '{}' which wasn't expected, or isn't valid in this context\n\nUSAGE:\n    executable set <mime> <handler>\n\nFor more information try --help", other);
                    std::process::exit(2);
                } else {
                    positional.push(other.clone());
                }
