fn render_table(rows: &[(String, String)]) {
    if rows.is_empty() {
        println!("┌──┐\n│  │\n└──┘");
        return;
    }

    let mut w1 = 0;
    let mut w2 = 0;
    for (k, v) in rows {
        w1 = w1.max(k.len());
        w2 = w2.max(v.len());
    }
    w1 += 2;
    w2 += 2;

    print!("┌");
    for _ in 0..w1 {
        print!("─");
    }
    print!("┬");
    for _ in 0..w2 {
        print!("─");
    }
    println!("┐");

    for (k, v) in rows {
        print!("│ {:<width1$} │ {:<width2$} │\n", k, v, width1 = w1 - 2, width2 = w2 - 2);
    }

    print!("└");
    for _ in 0..w1 {
        print!("─");
    }
    print!("┴");
    for _ in 0..w2 {
        print!("─");
    }
    println!("┘");
}

