        }
    };

    if !json {
        println!("{}", handler);
    } else {
        let entry = load_desktop_entry(&handler).unwrap_or_default();
        let tokens = parse_exec(&entry.exec);
        let filtered: Vec<String> = tokens
            .into_iter()
            .filter(|t| t != "%f" && t != "%F" && t != "%u" && t != "%U")
            .collect();

        let cmd = if filtered.len() == 1 {
            format!("{} ", filtered[0])
        } else if filtered.len() > 1 {
            filtered.join(" ")
        } else {
            String::new()
        };

        let json_str = format!(
            "{{\"handler\":{},\"name\":{},\"cmd\":{}}}",
            escape_json(&handler),
            escape_json(&entry.name),
            escape_json(&cmd)
        );
        println!("{}", json_str);
    }
}

fn escape_json(s: &str) -> String {
    let mut out = String::with_capacity(s.len() + 2);
    out.push('"');
    for ch in s.chars() {
        match ch {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            c => out.push(c),
        }
    }
    out.push('"');
    out
}

