fn parse_mime(s: &str) -> Result<String, String> {
    if s.starts_with('.') {
        let ext = &s[1..];
        if let Some(mime) = lookup_ext(ext) {
            return Ok(mime);
        } else {
            return Err(format!("could not figure out the mime type of '{}'", s));
        }
    }

    if !s.contains('/') {
        return Err("mime parse error: a slash (/) was missing between the type and subtype".to_string());
    }

    let parts: Vec<&str> = s.split('/').collect();
    if parts[0].is_empty() {
        return Err("mime parse error: an invalid token was encountered, 2F at position 0".to_string());
    }

    let mut pos = 0;
    for (i, part) in parts.iter().enumerate() {
        if i > 0 {
            if part.is_empty() && i == parts.len() - 1 {
                return Err(format!("mime parse error: an invalid token was encountered, 2F at position {}", pos));
            }
            pos += 1;
        }
        for ch in part.chars() {
            if !is_valid_mime_token_char(ch) {
                return Err(format!("mime parse error: an invalid token was encountered, {:02X} at position {}", ch as u32, pos));
            }
            pos += ch.len_utf8();
        }
    }

    Ok(s.to_string())
}

fn is_valid_mime_token_char(ch: char) -> bool {
    ch.is_ascii_alphanumeric() || "!#$%&'*+-.^_`|~".contains(ch)
}

fn lookup_ext(ext: &str) -> Option<String> {
    let ext_lower = ext.to_lowercase();
    let glob_target = format!("*.{}", ext_lower);

    let mut globs_paths = Vec::new();
    if let Ok(data_home) = env::var("XDG_DATA_HOME") {
        globs_paths.push(PathBuf::from(data_home).join("mime/globs2"));
    } else if let Ok(home) = env::var("HOME") {
        globs_paths.push(PathBuf::from(home).join(".local/share/mime/globs2"));
    }

    let data_dirs = env::var("XDG_DATA_DIRS").unwrap_or_else(|_| "/usr/local/share:/usr/share".to_string());
    for dir in data_dirs.split(':') {
        if !dir.is_empty() {
            globs_paths.push(PathBuf::from(dir).join("mime/globs2"));
        }
    }

    for path in globs_paths {
        if let Ok(content) = fs::read_to_string(&path) {
            for line in content.lines() {
                let line = line.trim();
                if line.is_empty() || line.starts_with('#') {
                    continue;
                }
                let parts: Vec<&str> = line.split(':').collect();
                if parts.len() >= 3 {
                    let mime = parts[1];
                    let glob = parts[2].to_lowercase();
                    if glob == glob_target {
                        return Some(mime.to_string());
                    }
                }
            }
        }
    }
    None
}

fn get_app_dirs() -> Vec<PathBuf> {
    let mut dirs = Vec::new();
    if let Ok(data_home) = env::var("XDG_DATA_HOME") {
        dirs.push(PathBuf::from(data_home).join("applications"));
    } else if let Ok(home) = env::var("HOME") {
        dirs.push(PathBuf::from(home).join(".local/share/applications"));
    }

    let data_dirs = env::var("XDG_DATA_DIRS").unwrap_or_else(|_| "/usr/local/share:/usr/share".to_string());
    for dir in data_dirs.split(':') {
        if !dir.is_empty() {
            dirs.push(PathBuf::from(dir).join("applications"));
        }
    }
    dirs
}

fn is_handler_valid(handler: &str) -> bool {
    if handler.starts_with('/') {
        return Path::new(handler).is_file();
    }
    for dir in get_app_dirs() {
        if dir.join(handler).is_file() {
            return true;
        }
    }
    false
}

fn validate_handler(handler: &str) -> Result<String, String> {
    if is_handler_valid(handler) {
        Ok(handler.to_string())
    } else {
        Err(format!("no handlers found for '{}'", handler))
    }
}

struct MimeAppsList {
    added_associations: BTreeMap<String, Vec<String>>,
    default_applications: BTreeMap<String, Vec<String>>,
    path: PathBuf,
}

impl MimeAppsList {
    fn load() -> Self {
        let (cfg_dir, path) = if let Ok(cfg_home) = env::var("XDG_CONFIG_HOME") {
            let dir = PathBuf::from(cfg_home);
            let p = dir.join("mimeapps.list");
            (dir, p)
        } else if let Ok(home) = env::var("HOME") {
            let dir = PathBuf::from(home).join(".config");
            let p = dir.join("mimeapps.list");
            (dir, p)
        } else {
            let dir = PathBuf::from(".config");
            let p = dir.join("mimeapps.list");
            (dir, p)
        };

        // Create handlr dir and touch mimeapps.list
        let _ = fs::create_dir_all(cfg_dir.join("handlr"));
        if !path.exists() {
            if let Some(parent) = path.parent() {
                let _ = fs::create_dir_all(parent);
            }
            let _ = File::create(&path);
        }

        let mut added_associations = BTreeMap::new();
        let mut default_applications = BTreeMap::new();

        if let Ok(content) = fs::read_to_string(&path) {
            let mut section = String::new();
            for line in content.lines() {
                let line = line.trim();
                if line.is_empty() || line.starts_with('#') {
                    continue;
                }
                if line.starts_with('[') && line.ends_with(']') {
                    section = line[1..line.len() - 1].trim().to_string();
                } else if let Some((k, v)) = line.split_once('=') {
                    let k = k.trim().to_string();
                    let vals: Vec<String> = v
                        .split(';')
                        .map(|s| s.trim().to_string())
                        .filter(|s| !s.is_empty())
                        .collect();
                    if section == "Added Associations" {
                        added_associations.insert(k, vals);
                    } else if section == "Default Applications" {
                        default_applications.insert(k, vals);
                    }
                }
            }
        }

        MimeAppsList {
            added_associations,
            default_applications,
            path,
        }
    }

    fn prune_invalid(&mut self) {
        self.added_associations.retain(|_, vals| {
            vals.retain(|v| is_handler_valid(v));
            !vals.is_empty()
        });
        self.default_applications.retain(|_, vals| {
            vals.retain(|v| is_handler_valid(v));
            !vals.is_empty()
        });
    }

    fn save(&mut self) {
        self.prune_invalid();
        if let Some(parent) = self.path.parent() {
            let _ = fs::create_dir_all(parent);
        }

        if self.added_associations.is_empty() && self.default_applications.is_empty() {
            let _ = fs::write(&self.path, "");
            return;
        }

        let mut out = String::new();
        out.push_str("[Added Associations]\n");
        for (k, vals) in &self.added_associations {
            out.push_str(k);
            out.push('=');
            for v in vals {
                out.push_str(v);
                out.push(';');
            }
            out.push('\n');
        }

        out.push_str("\n[Default Applications]\n");
        for (k, vals) in &self.default_applications {
            out.push_str(k);
            out.push('=');
            for v in vals {
                out.push_str(v);
                out.push(';');
            }
            out.push('\n');
        }

        let _ = fs::write(&self.path, out);
    }
}

#[derive(Default)]
struct DesktopEntry {
    name: String,
    exec: String,
    mime_types: Vec<String>,
    terminal: bool,
}

fn load_desktop_entry(handler: &str) -> Option<DesktopEntry> {
    let path = if handler.starts_with('/') {
        PathBuf::from(handler)
    } else {
        let mut found = None;
        for dir in get_app_dirs() {
            let p = dir.join(handler);
            if p.is_file() {
                found = Some(p);
                break;
            }
        }
        found?
    };

    let content = fs::read_to_string(&path).ok()?;
    let mut in_desktop_entry = false;
    let mut name = None;
    let mut exec = String::new();
    let mut mime_types = Vec::new();
    let mut terminal = false;

    for line in content.lines() {
        let line = line.trim();
        if line.is_empty() || line.starts_with('#') {
            continue;
        }
        if line.starts_with('[') && line.ends_with(']') {
            let sec = line[1..line.len() - 1].trim();
            in_desktop_entry = sec == "Desktop Entry";
            continue;
        }
        if !in_desktop_entry {
            continue;
        }
        if let Some((k, v)) = line.split_once('=') {
            let k = k.trim();
            let v = v.trim();
            if k == "Name" {
                if name.is_none() {
                    name = Some(v.to_string());
                }
            } else if k.starts_with("Name[") && name.is_none() {
                name = Some(v.to_string());
            } else if k == "Exec" {
                exec = v.to_string();
            } else if k == "MimeType" {
                mime_types = v
                    .split(';')
                    .map(|s| s.trim().to_string())
                    .filter(|s| !s.is_empty())
                    .collect();
            } else if k == "Terminal" {
                terminal = v.eq_ignore_ascii_case("true");
            }
        }
    }

    Some(DesktopEntry {
        name: name.unwrap_or_default(),
        exec,
        mime_types,
        terminal,
    })
}

fn get_system_apps() -> BTreeMap<String, Vec<String>> {
    let mut map: BTreeMap<String, Vec<String>> = BTreeMap::new();
    for dir in get_app_dirs() {
        if let Ok(entries) = fs::read_dir(dir) {
            for entry in entries.flatten() {
                let path = entry.path();
                if path.is_file() && path.extension().map_or(false, |ext| ext == "desktop") {
                    let filename = entry.file_name().to_string_lossy().to_string();
                    if let Some(desktop) = load_desktop_entry(&filename) {
                        for m in desktop.mime_types {
                            let vec = map.entry(m).or_default();
                            if !vec.contains(&filename) {
                                vec.push(filename.clone());
                            }
                        }
                    }
                }
            }
        }
    }
    map
}

fn find_default_handler(mime: &str, mimeapps: &MimeAppsList) -> Option<String> {
    // 1. Exact match in Default Applications
    if let Some(vals) = mimeapps.default_applications.get(mime) {
        for v in vals {
            if is_handler_valid(v) {
                return Some(v.clone());
            }
        }
    }

    // 2. Wildcard match in Default Applications
    if let Some((type_prefix, _)) = mime.split_once('/') {
        let wildcard = format!("{}/*", type_prefix);
        if let Some(vals) = mimeapps.default_applications.get(&wildcard) {
            for v in vals {
                if is_handler_valid(v) {
                    return Some(v.clone());
                }
            }
        }
    }

    // 3. Exact match in System Apps
    let sys_apps = get_system_apps();
    if let Some(vals) = sys_apps.get(mime) {
        for v in vals {
            if is_handler_valid(v) {
                return Some(v.clone());
            }
        }
    }

    // 4. Wildcard match in System Apps
    if let Some((type_prefix, _)) = mime.split_once('/') {
        let wildcard = format!("{}/*", type_prefix);
        if let Some(vals) = sys_apps.get(&wildcard) {
            for v in vals {
                if is_handler_valid(v) {
                    return Some(v.clone());
                }
            }
        }
    }

    None
}

fn render_table(rows: &[(String, String)]) {
    if rows.is_empty() {
        println!("┌──┐\n│  │\n└──┘");
        return;
    }

    let mut w1 = 0;
    let mut w2 = 0;
    for (k, v) in rows {
        w1 = w1.max(k.len());
        w2 = w2.max(v.len());
    }
    w1 += 2;
    w2 += 2;

    print!("┌");
    for _ in 0..w1 {
        print!("─");
    }
    print!("┬");
    for _ in 0..w2 {
        print!("─");
    }
    println!("┐");

    for (k, v) in rows {
        print!("│ {:<width1$} │ {:<width2$} │\n", k, v, width1 = w1 - 2, width2 = w2 - 2);
    }

    print!("└");
    for _ in 0..w1 {
        print!("─");
    }
    print!("┴");
    for _ in 0..w2 {
        print!("─");
    }
    println!("┘");
}

fn handle_list(args: &[String]) {
    let mut all = false;
    for arg in args {
        match arg.as_str() {
            "-a" | "--all" => all = true,
            "-h" | "--help" => {
                println!("executable-list \nList default apps and the associated handlers\n\nUSAGE:\n    executable list [FLAGS]\n\nFLAGS:\n    -a, --all        \n    -h, --help       Prints help information\n    -V, --version    Prints version information");
                std::process::exit(0);
            }
            "-V" | "--version" => {
                println!("executable-list ");
                std::process::exit(0);
            }
            other => print_arg_error(other, "list [FLAGS]"),
        }
    }

    let mimeapps = MimeAppsList::load();

    if !all {
        let mut rows = Vec::new();
        for (k, vals) in &mimeapps.default_applications {
            let valid_vals: Vec<String> = vals.iter().filter(|v| is_handler_valid(v)).cloned().collect();
            if !valid_vals.is_empty() {
                rows.push((k.clone(), valid_vals.join(", ")));
            }
        }
        render_table(&rows);
    } else {
        println!("Default Apps");
        let mut def_rows = Vec::new();
        for (k, vals) in &mimeapps.default_applications {
            let valid_vals: Vec<String> = vals.iter().filter(|v| is_handler_valid(v)).cloned().collect();
            if !valid_vals.is_empty() {
                def_rows.push((k.clone(), valid_vals.join(", ")));
            }
        }
        render_table(&def_rows);

        let mut add_rows = Vec::new();
        for (k, vals) in &mimeapps.added_associations {
            let valid_vals: Vec<String> = vals.iter().filter(|v| is_handler_valid(v)).cloned().collect();
            if !valid_vals.is_empty() {
                add_rows.push((k.clone(), valid_vals.join(", ")));
            }
        }
        if !add_rows.is_empty() {
            println!("Added Associations");
            render_table(&add_rows);
        }

        println!("System Apps");
        let sys_apps = get_system_apps();
        let mut sys_rows = Vec::new();
        for (k, vals) in &sys_apps {
            let valid_vals: Vec<String> = vals.iter().filter(|v| is_handler_valid(v)).cloned().collect();
            if !valid_vals.is_empty() {
                sys_rows.push((k.clone(), valid_vals.join(", ")));
            }
        }
        render_table(&sys_rows);
    }
}

fn parse_exec(exec: &str) -> Vec<String> {
    let mut tokens = Vec::new();
    let mut current = String::new();
    let mut in_double_quote = false;
    let mut in_single_quote = false;
    let mut escaped = false;

    for ch in exec.chars() {
        if escaped {
            current.push(ch);
            escaped = false;
            continue;
        }
        if ch == '\\' && !in_single_quote {
            escaped = true;
            continue;
        }
        if ch == '"' && !in_single_quote {
            in_double_quote = !in_double_quote;
            continue;
        }
        if ch == '\'' && !in_double_quote {
            in_single_quote = !in_single_quote;
            continue;
        }
        if ch.is_whitespace() && !in_double_quote && !in_single_quote {
            if !current.is_empty() {
                tokens.push(current.clone());
                current.clear();
            }
            continue;
        }
        current.push(ch);
    }
    if !current.is_empty() {
        tokens.push(current);
    }
    tokens
}

fn handle_get(args: &[String]) {
    let mut json = false;
    let mut mime_arg = None;

    for arg in args {
        match arg.as_str() {
            "--json" => json = true,
            "-h" | "--help" => {
                println!("executable-get \nGet handler for this mime/extension\n\nUSAGE:\n    executable get [FLAGS] <mime>\n\nARGS:\n    <mime>    \n\nFLAGS:\n        --json       \n    -h, --help       Prints help information\n    -V, --version    Prints version information");
                std::process::exit(0);
            }
            "-V" | "--version" => {
                println!("executable-get ");
                std::process::exit(0);
            }
            other => {
                if other.starts_with('-') {
                    print_arg_error(other, "get [FLAGS] <mime>");
                } else if mime_arg.is_none() {
                    mime_arg = Some(other.to_string());
                } else {
                    print_arg_error(other, "get [FLAGS] <mime>");
                }
            }
        }
    }

    let mime_raw = match mime_arg {
        Some(m) => m,
        None => {
            eprintln!("error: The following required arguments were not provided:\n    <mime>\n\nUSAGE:\n    executable get [FLAGS] <mime>\n\nFor more information try --help");
            std::process::exit(2);
        }
    };

    let mime = match parse_mime(&mime_raw) {
        Ok(m) => m,
        Err(err_msg) => {
            eprintln!("error: Invalid value for '<mime>': {}\n\nFor more information try --help", err_msg);
            std::process::exit(2);
        }
    };

    let mimeapps = MimeAppsList::load();
    let handler = match find_default_handler(&mime, &mimeapps) {
        Some(h) => h,
        None => {
            eprintln!("Error: Io(Os {{ code: 2, kind: NotFound, message: \"No such file or directory\" }})");
            std::process::exit(1);
        }
    };

    if !json {
        println!("{}", handler);
    } else {
        let entry = load_desktop_entry(&handler).unwrap_or_default();
        let tokens = parse_exec(&entry.exec);
        let filtered: Vec<String> = tokens
            .into_iter()
            .filter(|t| t != "%f" && t != "%F" && t != "%u" && t != "%U")
            .collect();

        let cmd = if filtered.len() == 1 {
            format!("{} ", filtered[0])
        } else if filtered.len() > 1 {
            filtered.join(" ")
        } else {
            String::new()
        };

        let json_str = format!(
            "{{\"handler\":{},\"name\":{},\"cmd\":{}}}",
            escape_json(&handler),
            escape_json(&entry.name),
            escape_json(&cmd)
        );
        println!("{}", json_str);
    }
}

fn escape_json(s: &str) -> String {
    let mut out = String::with_capacity(s.len() + 2);
    out.push('"');
    for ch in s.chars() {
        match ch {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            c => out.push(c),
        }
    }
    out.push('"');
    out
}

fn handle_set(args: &[String]) {
    let mut positional = Vec::new();
    for arg in args {
        match arg.as_str() {
            "-h" | "--help" => {
                println!("executable-set \nSet the default handler for mime/extension\n\nUSAGE:\n    executable set <mime> <handler>\n\nARGS:\n    <mime>       \n    <handler>    \n\nFLAGS:\n    -h, --help       Prints help information\n    -V, --version    Prints version information");
                std::process::exit(0);
            }
            "-V" | "--version" => {
                println!("executable-set ");
                std::process::exit(0);
            }
            other => {
                if other.starts_with('-') {
                    print_arg_error(other, "set <mime> <handler>");
                } else {
                    positional.push(other.to_string());
                }
            }
        }
    }

    if positional.is_empty() {
        eprintln!("error: The following required arguments were not provided:\n    <mime>\n    <handler>\n\nUSAGE:\n    executable set <mime> <handler>\n\nFor more information try --help");
        std::process::exit(2);
    } else if positional.len() == 1 {
        eprintln!("error: The following required arguments were not provided:\n    <handler>\n\nUSAGE:\n    executable set <mime> <handler>\n\nFor more information try --help");
        std::process::exit(2);
    } else if positional.len() > 2 {
        print_arg_error(&positional[2], "set <mime> <handler>");
    }

    let mime = match parse_mime(&positional[0]) {
        Ok(m) => m,
        Err(err_msg) => {
            eprintln!("error: Invalid value for '<mime>': {}\n\nFor more information try --help", err_msg);
            std::process::exit(2);
        }
    };

    let handler = match validate_handler(&positional[1]) {
        Ok(h) => h,
        Err(err_msg) => {
            eprintln!("error: Invalid value for '<handler>': {}\n\nFor more information try --help", err_msg);
            std::process::exit(2);
        }
    };

    let mut mimeapps = MimeAppsList::load();
    mimeapps.default_applications.insert(mime, vec![handler]);
    mimeapps.save();
}

fn handle_add(args: &[String]) {
    let mut positional = Vec::new();
    for arg in args {
        match arg.as_str() {
            "-h" | "--help" => {
                println!("executable-add \nAdd a handler for given mime/extension Note that the first handler is the default\n\nUSAGE:\n    executable add <mime> <handler>\n\nARGS:\n    <mime>       \n    <handler>    \n\nFLAGS:\n    -h, --help       Prints help information\n    -V, --version    Prints version information");
                std::process::exit(0);
            }
            "-V" | "--version" => {
                println!("executable-add ");
                std::process::exit(0);
            }
            other => {
                if other.starts_with('-') {
                    print_arg_error(other, "add <mime> <handler>");
                } else {
                    positional.push(other.to_string());
                }
            }
        }
    }

    if positional.is_empty() {
        eprintln!("error: The following required arguments were not provided:\n    <mime>\n    <handler>\n\nUSAGE:\n    executable add <mime> <handler>\n\nFor more information try --help");
        std::process::exit(2);
    } else if positional.len() == 1 {
        eprintln!("error: The following required arguments were not provided:\n    <handler>\n\nUSAGE:\n    executable add <mime> <handler>\n\nFor more information try --help");
        std::process::exit(2);
    } else if positional.len() > 2 {
        print_arg_error(&positional[2], "add <mime> <handler>");
    }

    let mime = match parse_mime(&positional[0]) {
        Ok(m) => m,
        Err(err_msg) => {
            eprintln!("error: Invalid value for '<mime>': {}\n\nFor more information try --help", err_msg);
            std::process::exit(2);
        }
    };

    let handler = match validate_handler(&positional[1]) {
        Ok(h) => h,
        Err(err_msg) => {
            eprintln!("error: Invalid value for '<handler>': {}\n\nFor more information try --help", err_msg);
            std::process::exit(2);
        }
    };

    let mut mimeapps = MimeAppsList::load();
    let entry = mimeapps.default_applications.entry(mime).or_default();
    entry.push(handler);
    mimeapps.save();
}

fn handle_unset(args: &[String]) {
    let mut positional = Vec::new();
    for arg in args {
        match arg.as_str() {
            "-h" | "--help" => {
                println!("executable-unset \nUnset the default handler for mime/extension\n\nUSAGE:\n    executable unset <mime>\n\nARGS:\n    <mime>    \n\nFLAGS:\n    -h, --help       Prints help information\n    -V, --version    Prints version information");
                std::process::exit(0);
            }
            "-V" | "--version" => {
                println!("executable-unset ");
                std::process::exit(0);
            }
            other => {
                if other.starts_with('-') {
                    print_arg_error(other, "unset <mime>");
                } else {
                    positional.push(other.to_string());
                }
            }
        }
    }

    if positional.is_empty() {
        eprintln!("error: The following required arguments were not provided:\n    <mime>\n\nUSAGE:\n    executable unset <mime>\n\nFor more information try --help");
        std::process::exit(2);
    } else if positional.len() > 1 {
        print_arg_error(&positional[1], "unset <mime>");
    }

    let mime = match parse_mime(&positional[0]) {
        Ok(m) => m,
        Err(err_msg) => {
            eprintln!("error: Invalid value for '<mime>': {}\n\nFor more information try --help", err_msg);
            std::process::exit(2);
        }
    };

    let mut mimeapps = MimeAppsList::load();
    mimeapps.default_applications.remove(&mime);
    mimeapps.save();
}

fn spawn_cmd(exec_str: &str, target_args: &[String], terminal: bool, mimeapps: &MimeAppsList) {
    let words = parse_exec(exec_str);
    let mut has_field_code = false;

    let mut new_words = Vec::new();
    for w in words {
        if w == "%f" || w == "%F" || w == "%u" || w == "%U" {
            has_field_code = true;
            for arg in target_args {
                new_words.push(arg.clone());
            }
        } else {
            new_words.push(w);
        }
    }
    if !has_field_code {
        for arg in target_args {
            new_words.push(arg.clone());
        }
    }

    if terminal {
        if let Some(term_h) = find_default_handler("x-scheme-handler/terminal", mimeapps) {
            if let Some(term_entry) = load_desktop_entry(&term_h) {
                let term_exec_words = parse_exec(&term_entry.exec);
                let mut final_words = Vec::new();
                for w in term_exec_words {
                    if w != "%f" && w != "%F" && w != "%u" && w != "%U" {
                        final_words.push(w);
                    }
                }
                final_words.push("-e".to_string());
                final_words.extend(new_words);
                new_words = final_words;
            }
        } else {
            eprintln!("Error: Io(Os {{ code: 2, kind: NotFound, message: \"No such file or directory\" }})");
            std::process::exit(1);
        }
    }

    if !new_words.is_empty() {
        if let Err(err) = Command::new(&new_words[0])
            .args(&new_words[1..])
            .stdin(Stdio::null())
            .stdout(Stdio::null())
            .stderr(Stdio::null())
            .spawn()
        {
            eprintln!("Error: {:?}", err);
            std::process::exit(1);
        }
    }
}

fn handle_launch(args: &[String]) {
    let mut positional = Vec::new();
    for arg in args {
        match arg.as_str() {
            "-h" | "--help" => {
                println!("executable-launch \nLaunch the handler for specified extension/mime with optional arguments\n\nUSAGE:\n    executable launch <mime> [args]...\n\nARGS:\n    <mime>       \n    <args>...    \n\nFLAGS:\n    -h, --help       Prints help information\n    -V, --version    Prints version information");
                std::process::exit(0);
            }
            "-V" | "--version" => {
                println!("executable-launch ");
                std::process::exit(0);
            }
            other => {
                if other.starts_with('-') && positional.is_empty() {
                    print_arg_error(other, "launch <mime> [args]...");
                } else {
                    positional.push(other.to_string());
                }
            }
        }
    }

    if positional.is_empty() {
        eprintln!("error: The following required arguments were not provided:\n    <mime>\n\nUSAGE:\n    executable launch <mime> [args]...\n\nFor more information try --help");
        std::process::exit(2);
    }

    let mime = match parse_mime(&positional[0]) {
        Ok(m) => m,
        Err(err_msg) => {
            eprintln!("error: Invalid value for '<mime>': {}\n\nFor more information try --help", err_msg);
            std::process::exit(2);
        }
    };

    let launch_args = positional[1..].to_vec();

    let mimeapps = MimeAppsList::load();
    let handler = match find_default_handler(&mime, &mimeapps) {
        Some(h) => h,
        None => {
            eprintln!("Error: Io(Os {{ code: 2, kind: NotFound, message: \"No such file or directory\" }})");
            std::process::exit(1);
        }
    };

    let entry = match load_desktop_entry(&handler) {
        Some(e) => e,
        None => {
            eprintln!("Error: Io(Os {{ code: 2, kind: NotFound, message: \"No such file or directory\" }})");
            std::process::exit(1);
        }
    };

    spawn_cmd(&entry.exec, &launch_args, entry.terminal, &mimeapps);
}

fn is_url_scheme(s: &str) -> Option<(String, String)> {
    if let Some((scheme, rest)) = s.split_once(':') {
        if !scheme.is_empty() && scheme.chars().next().unwrap().is_ascii_alphabetic() && scheme.chars().all(|c| c.is_ascii_alphanumeric() || "+-.".contains(c)) {
            let scheme_lower = scheme.to_lowercase();
            let mut normalized_url = s.to_string();
            if (scheme_lower == "http" || scheme_lower == "https" || scheme_lower == "ftp") && !rest.contains('/') {
                normalized_url.push('/');
            }
            return Some((format!("x-scheme-handler/{}", scheme_lower), normalized_url));
        }
    }
    None
}

fn handle_open(args: &[String]) {
    let mut positional = Vec::new();
    for arg in args {
        match arg.as_str() {
            "-h" | "--help" => {
                println!("executable-open \nOpen a path/URL with its default handler\n\nUSAGE:\n    executable open <paths>...\n\nARGS:\n    <paths>...    \n\nFLAGS:\n    -h, --help       Prints help information\n    -V, --version    Prints version information");
                std::process::exit(0);
            }
            "-V" | "--version" => {
                println!("executable-open ");
                std::process::exit(0);
            }
            other => {
                if other.starts_with('-') && positional.is_empty() {
                    print_arg_error(other, "open <paths>...");
                } else {
                    positional.push(other.to_string());
                }
            }
        }
    }

    if positional.is_empty() {
        eprintln!("error: The following required arguments were not provided:\n    <paths>...\n\nUSAGE:\n    executable open <paths>...\n\nFor more information try --help");
        std::process::exit(2);
    }

    let mimeapps = MimeAppsList::load();

    // Map: handler_name -> Vec<target_str>
    let mut handler_groups: Vec<(String, Vec<String>)> = Vec::new();

    for path_str in positional {
        if let Some((scheme_mime, norm_url)) = is_url_scheme(&path_str) {
            let handler = match find_default_handler(&scheme_mime, &mimeapps) {
                Some(h) => h,
                None => {
                    eprintln!("Error: Io(Os {{ code: 2, kind: NotFound, message: \"No such file or directory\" }})");
                    std::process::exit(1);
                }
            };
            if let Some((_, list)) = handler_groups.iter_mut().find(|(h, _)| h == &handler) {
                list.push(norm_url);
            } else {
                handler_groups.push((handler, vec![norm_url]));
            }
        } else {
            let path = Path::new(&path_str);
            let (mime, target) = if path.is_dir() {
                let abs = fs::canonicalize(path).unwrap_or_else(|_| path.to_path_buf());
                ("inode/directory".to_string(), abs.to_string_lossy().to_string())
            } else {
                let ext = path.extension().and_then(|e| e.to_str()).unwrap_or("");
                let mime = match lookup_ext(ext) {
                    Some(m) => m,
                    None => {
                        eprintln!("Error: Io(Os {{ code: 2, kind: NotFound, message: \"No such file or directory\" }})");
                        std::process::exit(1);
                    }
                };
                let abs = fs::canonicalize(path).unwrap_or_else(|_| {
                    if path.is_relative() {
                        if let Ok(cur) = env::current_dir() {
                            cur.join(path)
                        } else {
                            path.to_path_buf()
                        }
                    } else {
                        path.to_path_buf()
                    }
                });
                (mime, abs.to_string_lossy().to_string())
            };

            let handler = match find_default_handler(&mime, &mimeapps) {
                Some(h) => h,
                None => {
                    eprintln!("Error: Io(Os {{ code: 2, kind: NotFound, message: \"No such file or directory\" }})");
                    std::process::exit(1);
                }
            };

            if let Some((_, list)) = handler_groups.iter_mut().find(|(h, _)| h == &handler) {
                list.push(target);
            } else {
                handler_groups.push((handler, vec![target]));
            }
        }
    }

    for (handler, targets) in handler_groups {
        let entry = match load_desktop_entry(&handler) {
            Some(e) => e,
            None => {
                eprintln!("Error: Io(Os {{ code: 2, kind: NotFound, message: \"No such file or directory\" }})");
                std::process::exit(1);
            }
        };

        let exec = &entry.exec;
        let is_multi = exec.contains("%F") || exec.contains("%U");

        if is_multi {
            spawn_cmd(exec, &targets, entry.terminal, &mimeapps);
        } else {
            for t in targets {
                spawn_cmd(exec, &[t], entry.terminal, &mimeapps);
            }
        }
    }
}
EOF"}

